from pathlib import Path
import json
root=Path(__file__).parent
rows=[
('cererea-cu-context','Cererea pentru instalații poate începe DEJA cu poze.','Un mesaj pregătit','Imaginează-ți o solicitare care începe cu localitatea, lucrarea dorită și două fotografii relevante. Ai un punct de plecare pentru discuție.\n\nPoți pregăti acest început chiar lângă contact: „Spune-ne localitatea, ce ai vrea să facem și trimite o fotografie de ansamblu și una de detaliu.”\n\nFotografiile oferă context. Evaluarea și prețul se stabilesc după ce clarificați lucrarea.\n\nNoi putem pune această invitație pe site-ul de instalații, lângă butonul de WhatsApp. În exemplul propus vezi cum alegi informațiile de cerut pentru prima conversație.', 'Ce poți cere în primul mesaj','Un model simplu pentru solicitările de instalații.', ['Prima discuție despre instalații poate începe MAI clar.','Pozele lucrării pot ajunge ÎNAINTE de primul apel.'], 'A sculptural charcoal smartphone on a plumber workbench beside copper fittings and a folded cream bathroom plan. Phone has only three labels: Localitate, Lucrare, Fotografii.', 'Large circular inset shows a wide view of the unfinished bathroom behind the request, not a duplicate of the phone.', 'Model de solicitare cu localitate, lucrare și fotografii; diferența dintre context și evaluare.'),
('fotografia-cu-explicatie','Lucrarea e gata. Ce o face UȘOR de înțeles online?','Portofoliu explicat','O fotografie cu traseele montate poate spune mai mult când are o explicație lângă ea.\n\nPentru fiecare lucrare pe care ai dreptul să o publici, notează ce ai făcut, în ce tip de spațiu și ce se vede în fotografie. De exemplu: „Distribuitor pentru încălzire în pardoseală, montat într-o casă.”\n\nAșa îi dai cititorului repere pentru a recunoaște un proiect apropiat de al lui.\n\nNoi putem organiza lucrările reale pe site, cu descrieri scurte. În continuare găsești o structură de prezentare pe care o poți aplica fotografiilor tale.', 'Cum prezinți o lucrare de instalații','O fotografie, contextul și explicația potrivită.', ['O fotografie de instalații capătă CONTEXT din câteva cuvinte.','Lucrarea ta poate spune MAI mult decât arată poza.'], 'A cream printed portfolio spread on an elegant workshop table, showing a neatly installed heating manifold. Copper and orange pencil accents.', 'Circular inset reveals a short caption card with exact label: Ce am montat. The inset adds the explanatory caption behind the portfolio.', 'Structură pentru prezentarea unei lucrări reale: intervenție, spațiu, fotografie și explicație.'),
('zona-de-lucru','Următoarea cerere poate începe chiar din ZONA ta.','Acoperire locală','Imaginează-ți că cineva citește despre montajul unui calorifer și recunoaște localitatea lui în zona ta de lucru. Știe deja dacă are sens să te contacteze.\n\nPe site, enumeră localitățile în care te deplasezi. Dacă acoperirea diferă în funcție de lucrare, explică acest lucru lângă listă.\n\nUn reper precis îl ajută să formuleze o cerere potrivită.\n\nNoi putem prezenta zona de intervenție alături de servicii. Vezi un exemplu de formulare și cum îl adaptezi la deplasările pe care le faci efectiv.', 'Cum arăți unde te deplasezi','Zona de lucru, explicată înainte de contact.', ['Localitatea din cerere poate fi DEJA un punct comun.','Un detaliu de pe site face deplasarea mai CLARĂ.'], 'A beautiful miniature cream town map on a plumber table, copper pipes in foreground and restrained orange location pins; no real geographic names.', 'Rectangular inset reveals a service-area list card with only label: Zona de lucru, and blank lines, connecting map to a website explanation.', 'Exemplu de listă de localități și condiții de deplasare; hartă ilustrativă.'),
('de-la-lucrare-la-contact','De la poza instalației la mesaj: pasul MIC dintre ele.','Contact contextual','Un vizitator se uită la o lucrare asemănătoare cu ce își dorește acasă. Acela este un loc firesc pentru o invitație la discuție.\n\nLângă fotografie și explicație poți pune: „Discutăm o lucrare asemănătoare”, urmat de contact. Omul vede ce poate face în continuare.\n\nÎncearcă traseul pe propriul telefon: deschide lucrarea și verifică dacă poți ajunge ușor la apel sau WhatsApp.\n\nNoi includem contact direct pe site și îl putem așeza lângă serviciile relevante. În exemplu vezi cum se leagă lucrarea de primul mesaj.', 'De la lucrare la primul mesaj','Un traseu simplu de verificat pe telefon.', ['O lucrare de instalații poate deschide CONVERSAȚIA.','După fotografia instalației, următorul pas poate fi SIMPLU.'], 'Close-up charcoal phone on cream plinth showing a large radiator installation image and one orange contact button with handset icon; copper elbow on table.', 'Circular inset shows a generic message composition pane with a small matching radiator thumbnail, no fake conversation or messages.', 'Demonstrație de traseu: lucrare, explicație, contact; fără promisiune de conversie.'),
('recomandarea-cu-link','O recomandare de instalator poate spune MAI mult decât un nume.','Recomandări cu context','Imaginează-ți că un client mulțumit trimite mai departe numele tău și un link cu serviciile și lucrările tale. Recomandarea are acum și context.\n\nPoți pregăti o pagină ușor de trimis: cine ești, ce lucrări faci, unde te deplasezi și cum te contactează omul.\n\nVerifică pagina pe telefon și asigură-te că aceste informații se găsesc ușor.\n\nNoi le putem aduna într-un site pentru activitatea ta de instalații. Vezi ce merită să găsească cineva când primește linkul tău.', 'Ce pui în linkul de recomandare','Servicii, lucrări, zonă și contact într-un loc.', ['Recomandarea poate ajunge DEJA cu lucrările tale.','Numele instalatorului e începutul. Ce adaugă LINKUL?'], 'Two charcoal phones on cream workshop bench with a copper fitting between them, one displaying a generic share symbol and the other a plumbing service portfolio.', 'Circular inset reveals the physical bathroom project represented by the shared portfolio. No chat quotes.', 'Structura paginii trimise odată cu recomandarea; scenariu, nu mărturie reală.'),
('intrebarea-potrivita','Pentru montajul caloriferului, prima întrebare poate SCHIMBA discuția.','Calificarea cererii','„Este o înlocuire sau un montaj într-un spațiu nou?”\n\nAceastă întrebare simplă îți oferă context pentru o solicitare de montaj calorifer. Apoi poți cere localitatea și o fotografie de ansamblu a locului.\n\nAlege întrebările după serviciul concret. Pentru altă lucrare, începutul conversației poate fi diferit.\n\nNoi putem explica pe site ce informații sunt utile înainte de contact. În exemplul propus vezi cum pregătești o solicitare pentru montaj, fără să înlocuiești evaluarea lucrării.', 'Cu ce întrebare începi solicitarea','Un exemplu pentru montajul unui calorifer.', ['Montaj nou sau înlocuire? Un început mai CLAR.','Cererea de montaj poate avea CONTEXT de la prima întrebare.'], 'An elegant radiator resting safely against a cream wall in a finished room, with plumber notebook in foreground and orange pencil.', 'Circular inset shows a two-choice note with exact labels: Înlocuire and Montaj nou; adds the project-context question.', 'Exemplu de întrebare contextuală, urmată de localitate și fotografie; evaluarea rămâne separată.'),
('poza-de-ansamblu','O poză cu baia poate pregăti MAI bine prima discuție.','Context vizual','Imaginează-ți o cerere pentru montajul unui obiect sanitar. Primești o fotografie de ansamblu și una a locului unde urmează lucrarea.\n\nCele două cadre pot oferi context diferit: primul arată spațiul, al doilea zona despre care vorbiți. Poți cere imagini făcute dintr-un loc sigur, fără demontări.\n\nExplică această diferență chiar lângă invitația de a trimite fotografii.\n\nNoi putem include indicația pe pagina serviciului. Vezi un exemplu de cerere care pregătește discuția, urmând ca soluția să fie stabilită după evaluare.', 'Ce fotografii cerem pentru context','Ansamblu și detaliu, înainte de evaluare.', ['Două cadre din baie. Ce îți arată FIECARE?','Prima discuție despre baie poate începe cu o imagine CLARĂ.'], 'A carefully composed cream bathroom with sink cabinet and a phone held at a normal safe distance showing the room, no person identity visible.', 'Circular inset shows closer external view of the sink installation location, intact fittings, no disassembly. The close-up adds detail to wide scene.', 'Diferența între fotografie de ansamblu și detaliu; nicio diagnosticare din imagini.'),
('serviciul-recunoscut','Clientul își poate recunoaște lucrarea din PRIMA propoziție.','Servicii pe înțeles','„Montaj și înlocuire baterii de baie și bucătărie.”\n\nEste un exemplu de formulare care spune concret ce lucrare poate cere omul. Pe pagina ta, folosește denumirile serviciilor pe care le faci efectiv.\n\nPentru fiecare serviciu, adaugă o explicație scurtă și spune ce informații îți sunt utile la contact.\n\nNoi putem organiza oferta ta de instalații în pagini și secțiuni ușor de parcurs. În continuare vezi cum transformi o listă de servicii într-o prezentare clară.', 'Cum explici serviciile de instalații','Denumiri concrete și următorul pas.', ['O propoziție face serviciul de instalații mai UȘOR de recunoscut.','Cererea potrivită poate începe cu un serviciu BINE explicat.'], 'Beautiful installed kitchen tap and a cream website service card on a tablet at side, copper accents and natural architectural light.', 'Rectangular inset reveals three illustrated service tiles: faucet, radiator, sink; no text except exact label Servicii.', 'Exemple de denumiri concrete; adaptare exclusiv la serviciile oferite efectiv.'),
('etapele-lucrarii','O instalație bine făcută are o POVESTE de arătat.','Etapele proiectului','Unele detalii ale unei lucrări se văd cel mai bine în timpul montajului. Le poți păstra în fotografii și explica pe site.\n\nPentru un proiect real, alege cadre din etape relevante și notează ce ai făcut în fiecare. Publică doar imaginile pentru care ai permisiunea necesară.\n\nCititorul poate înțelege astfel cum ai abordat acea lucrare. Fotografiile ilustrează procesul, fără să țină loc de verificare tehnică.\n\nNoi putem organiza povestea proiectului într-o prezentare clară. Vezi o structură simplă pentru fotografiile din etapele lucrării.', 'Cum prezinți etapele unei instalații','O structură pentru fotografiile proiectelor tale.', ['Ce poți arăta dintr-o instalație ÎNAINTE de finisaje?','Fotografiile din timpul montajului adaugă CONTEXT lucrării.'], 'Editorial overhead flat-lay of cream architectural plan and three printed photographs of a plumbing project at different stages, copper and orange pencil accents.', 'Circular inset reveals a close-up of a neat pipe route before finishing, showing the intermediate step hidden by final finished room.', 'Structură pentru etapele unui proiect real; vizual generat ilustrativ, nu portofoliu.'),
('programul-de-contact','Programul instalatorului poate face următorul apel mai SIMPLU.','Așteptări clare','Imaginează-ți că cineva găsește serviciul de care are nevoie și vede chiar lângă telefon intervalul în care răspunzi.\n\nPe site, poți separa programul de contact de programarea lucrărilor. De exemplu, explică în ce interval preiei apeluri și cum confirmați disponibilitatea pentru intervenție.\n\nCompletează doar programul pe care îl poți respecta.\n\nNoi putem așeza aceste informații lângă butoanele de contact. Vezi cum formulezi un program clar, cu pașii următori pentru o solicitare.', 'Cum explici când poți fi contactat','Programul de contact și stabilirea intervenției.', ['Un detaliu lângă telefon pregătește MAI bine apelul.','Pentru următoarea intervenție, programul poate fi DEJA clar.'], 'Warm morning light across plumber notebook, work gloves and phone on cream desk. Notebook uses abstract calendar blocks, no times or fake appointments.', 'Circular inset reveals website contact card with handset symbol and label Program de contact, empty neutral schedule lines.', 'Separarea programului de contact de confirmarea disponibilității; fără disponibilitate permanentă inventată.'),
('intrebarea-frecventa','O întrebare despre instalații poate primi răspuns ÎNAINTE de apel.','Întrebări frecvente','„Veniți și pentru o singură baterie de schimbat?”\n\nEste un exemplu de întrebare pe care o poți lămuri pe site, dacă descrie serviciile tale. Un răspuns scurt îl ajută pe om să înțeleagă ce poate solicita.\n\nPornește de la întrebările pe care chiar le primești. Pentru fiecare, scrie ce oferi și ce trebuie discutat înainte de confirmarea lucrării.\n\nNoi putem aduna răspunsurile într-o secțiune clară. Vezi cum alegi întrebările care merită explicate lângă serviciile de instalații.', 'Ce întrebări merită puse pe site','Răspunsuri utile înainte de prima conversație.', ['Prima conversație cu instalatorul poate începe MAI departe.','Întrebările despre montaj au un loc FIRESC pe site.'], 'A premium brass tap on cream work surface next to phone displaying a simple question-card interface with question mark, charcoal/orange palette.', 'Rectangular inset reveals a single tap being installed in a clean sink, illustrating the small-job context behind the question.', 'Metodă de selectare a întrebărilor reale; replica din text este exemplu, nu citat de client.'),
('cartea-de-vizita','Cartea de vizită a instalatorului poate arăta și LUCRĂRI.','Punte offline-online','Imaginează-ți că lași o carte de vizită după o lucrare. Pe ea există și adresa paginii unde se văd serviciile și proiectele tale.\n\nPoți adăuga un cod QR către acea pagină. Testează codul de pe varianta tipărită și verifică dacă pagina se citește bine pe telefon.\n\nAșa pregătești un drum concret de la un obiect pe hârtie la mai multe informații despre activitatea ta.\n\nNoi putem construi pagina de destinație. În exemplu vezi ce informații merită să găsească omul după scanare.', 'Ce găsește omul după cartea de vizită','O continuare online pentru serviciile tale.', ['O carte de vizită. O continuare MAI bogată pentru lucrările tale.','Din trusa instalatorului, un detaliu deschide PORTOFOLIUL.'], 'Cream blank business card with a generic non-scannable square mosaic, lying on neatly organized plumber tool bag beside copper fitting. No fabricated address or phone.', 'Circular inset reveals a phone portfolio of plumbing project thumbnails, the online destination of the physical card.', 'Metodă de conectare a cărții de vizită la site; grafica nu conține cod QR funcțional, tiparul nu este inclus.'),
('site-pe-telefon','Site-ul de instalații are un test BUN chiar în buzunar.','Verificare pe mobil','Deschide pagina ta pe telefon, ca și cum ai vedea-o pentru prima dată.\n\nPoți afla ce lucrări faci, în ce zonă te deplasezi și cum te contactează cineva? Apasă apoi butonul de apel sau mesaj și verifică unde ajungi.\n\nAcest mic test îți arată concret dacă informațiile esențiale și contactul sunt ușor de găsit pe acel telefon.\n\nNoi construim site-uri adaptate pentru mobil. În continuare găsești pașii testului și un exemplu de pagină pentru instalații.', 'Testează pagina de pe telefon','Servicii, zonă și contact: un traseu de verificat.', ['Pagina instalatorului poate fi verificată chiar ACUM.','Trei lucruri de găsit UȘOR pe site-ul de instalații.'], 'Hero smartphone in portrait on charcoal pedestal with cream plumbing service page and large orange contact button, real work glove and copper parts beside it.', 'Circular inset magnifies fingertip approaching the contact button and a handset icon, revealing the contact step. No analytics.', 'Test manual pentru servicii, zonă și contact; nu dovadă de performanță comercială.'),
('pregatirea-ofertei','O cerere pentru instalații poate pregăti DEJA discuția despre ofertă.','Pregătirea estimării','Imaginează-ți că înainte de a discuta costul afli ce montaj se dorește, localitatea și dacă obiectul sanitar este deja cumpărat.\n\nPoți cere aceste informații lângă contact și explica ce urmează: clarificați lucrarea, stabiliți dacă este necesară o vizită și apoi discutați oferta.\n\nAdaptează pașii la felul în care lucrezi. Solicitarea inițială oferă context, iar prețul final depinde de evaluare și de ce conveniți.\n\nNoi putem explica acest traseu pe site. Vezi un exemplu de structură pentru o cerere mai bine pregătită.', 'Ce afli înainte de discuția despre preț','Informațiile inițiale și pașii către ofertă.', ['Discuția despre montaj poate începe cu detalii CONCRETE.','Înainte de ofertă, o cerere poate avea MAI mult context.'], 'Plumber planning desk with a boxed new faucet, cream notebook and smartphone showing a simple request checklist, orange pencil, no money or pricing.', 'Circular inset shows three pictograms for location, work and purchased fixture with exact label: Detalii utile.', 'Informații pentru pregătirea conversației; nu calcul automat, ofertare garantată sau preț din fotografii.'),
('serviciul-sezonier','Lucrarea de încălzire merită un loc VIZIBIL pe site.','Serviciu în prim-plan','Când vrei să prezinți montajul caloriferelor, poți începe pagina chiar cu acel serviciu și cu o lucrare relevantă.\n\nAlege o fotografie reală pe care o poți publica, explică ce montezi și spune ce informații ceri pentru discuție. Păstrează la vedere și zona de lucru.\n\nPoți schimba serviciul din prim-plan atunci când prioritățile activității tale se schimbă.\n\nNoi oferim administrarea site-ului și putem actualiza prezentarea la cererea ta, în limitele planului ales. Vezi cum pregătești un brief clar pentru această actualizare.', 'Cum aduci un serviciu în prim-plan','Un exemplu pentru montajul caloriferelor.', ['Site-ul poate urmări NOUA prioritate a lucrărilor tale.','Montajul caloriferelor poate avea PROPRIA prezentare.'], 'Beautiful cream room with a newly installed charcoal radiator and a tablet foreground featuring matching radiator service image, restrained orange accent.', 'Rectangular inset reveals a simple update brief on paper with icons for photo, service and location, exact label Actualizare.', 'Exemplu de actualizare editorială cerută de client; disponibilitatea serviciului și limitele planului se confirmă.'),
('previzualizarea','Site-ul pentru instalații poate prinde FORMĂ înainte să decizi.','Vizualizarea ofertei','Imaginează-ți că vezi serviciile tale așezate într-o pagină: lucrări, zonă de intervenție și contact. Devine mai ușor să discuți ce vrei să păstrezi sau să schimbi.\n\nCând analizezi o propunere de site, verifică aceste lucruri și deschide-o pe telefon. Notează concret ce informație lipsește sau trebuie corectată.\n\nNoi prezentăm pe pagina dedicată instalatorilor un exemplu de site și pașii colaborării. Vezi modelul și cum funcționează etapa de previzualizare înainte de plată, în condițiile ofertei.', 'Vezi un exemplu de site pentru instalatori','Modelul de prezentare și pașii colaborării.', ['Serviciile tale de instalații pot avea DEJA o formă online.','Înainte de decizie, site-ul poate deveni CONCRET.'], 'Art-directed cream desktop scene with laptop and smartphone displaying coordinated plumbing website layouts, copper fitting and folded plan alongside.', 'Circular inset reveals the mobile layout and prominent handset button, providing the mobile detail beyond large desktop overview.', 'Exemplu de site și procesul de preview existent în cod; condițiile comerciale și publicarea live se verifică.')
]
base='''Use case: ads-marketing. Generate ONE finished standalone portrait 4:5 Romanian Meta ad, preferably 1080x1350 or equivalent. Brand visual language: warm cream #f7f5ef, charcoal #242320, burnt orange #d9532b, premium editorial photography/compositing with tactile realistic materials and precise clean typography. Audience is Romanian plumbers selling their services, NOT householders shopping for plumbing. Rich art-directed main scene upper 63 percent, meaningful picture-in-picture inset upper right approximately 30 percent width with thin cream rim, subtle orange connector only if useful. Large charcoal headline panel lower 37 percent, subtly torn upper edge. Headline in bold geometric sans-serif, large cream letters, only the ONE uppercase keyword in burnt orange, remaining words sentence case, accurate Romanian diacritics, 5 percent safe margins. Fully opaque baked background, no alpha transparency. Add small upper-left 'Exemplu ilustrativ', plus discreet lower corner wordmark 'webform' to identify source. No CTA button in image, no extra copy, no fake testimonials, no prices, no quantified success, no fake actual customers, no watermarks. All websites and work examples are illustrative. Do not repeat same picture in inset: it adds explanatory information. Return one artwork, never a grid. '''
ads=[]
for i,r in enumerate(rows,1):
 slug,hook,angle,copy,link,description,alts,scene,inset,lesson=r
 a=dict(id=i,slug=slug,headline=hook,angle=angle,copy=copy,link=link,description=description,alternatives=alts,scene=scene,inset=inset,lesson=lesson,cta='Learn more',file=f'{i:02d}-{slug}.png',audience='Instalatori independenți și proprietari de firme de instalații din România',situation=copy.split('\n\n')[0],hypothesis=f'Ipoteză de test: unghiul «{angle.lower()}» atrage instalatori interesați de prezentarea online a serviciilor.',benefit=lesson,basis='Metodă aplicabilă și/sau scenariu explicit, fără rezultate comerciale măsurate. Imaginile generate sunt exemple ilustrative.',destination='continuari.html#reclama-'+str(i) if i<16 else '/instalatii',publication='Continuare editorială inclusă în pachet, nepublicată.' if i<16 else 'Pagină existentă în cod; disponibilitatea și conținutul live nu au fost verificate.',verify='Fotografiile reale, serviciile, zona și programul se adaptează fiecărui instalator. Publică această continuare înainte de utilizarea reclamei.' if i<16 else 'Verifică pagina live, exemplul și condițiile actuale de preview înainte de lansare.')
 a['prompt']=base+'Main scene: '+scene+' Inset: '+inset+' Exact headline, reproduce verbatim: '+json.dumps(hook,ensure_ascii=False)+'.'
 ads.append(a)
assert len(ads)==16
for a in ads:
 for h in [a['headline']]+a['alternatives']:
  assert len([w for w in h.split() if w.isupper() and len(w)>1])==1,h
(root/'concepte.json').write_text(json.dumps(ads,ensure_ascii=False,indent=2))
print('16 concepte și 32 hook-uri alternative verificate.')
